import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

@Configuration(proxyBeanMethods = false)
@EnableConfigurationProperties(ExportClientConfiguration.ExportProperties.class)
public class ExportClientConfiguration {
    @ConfigurationProperties("exports")
    public record ExportProperties(String baseUrl, boolean bufferForDiagnostics) {}

    @Bean
    ExportPeer exportPeer(RestClient.Builder builder, ExportProperties settings) {
        return new ExportPeer(builder.clone()
                .baseUrl(settings.baseUrl())
                .bufferContent((uri, method) -> settings.bufferForDiagnostics())
                .build());
    }
}

