import org.springframework.web.client.RestClient;

public final class ExportPeer {
    private static final int LIMIT = 1024;
    private final RestClient client;

    public ExportPeer(RestClient client) {
        this.client = client;
    }

    public byte[] download() {
        return client.get().uri("/export").exchange((request, response) -> {
            if (!response.getStatusCode().is2xxSuccessful()) {
                throw new PeerFailure(response.getStatusCode().value());
            }
            if (response.getHeaders().getContentLength() > LIMIT) {
                throw new TooLarge();
            }
            byte[] body = response.getBody().readNBytes(LIMIT + 1);
            if (body.length > LIMIT) {
                throw new TooLarge();
            }
            return body;
        });
    }

    public static final class TooLarge extends RuntimeException {}
    public static final class PeerFailure extends RuntimeException {
        public final int status;
        public PeerFailure(int status) {
            this.status = status;
        }
    }
}

